findings.suggestion:
在 paths.py 中封装统一的安全解析函数，并让下载先校验归属：
# paths.py
def storage_path(relative_path):
    root = os.path.realpath(STORAGE_ROOT)
    full = os.path.realpath(os.path.join(root, relative_path))
    if full != root and not full.startswith(root + os.sep):
        raise ValueError("illegal path")
    return full

# api.py
try:
    full = paths.storage_path(relative_path)
except ValueError:
    return {"status": 400, "message": "非法路径"}
user_root = os.path.realpath(os.path.join(STORAGE_ROOT, CURRENT_USER))
if not full.startswith(user_root + os.sep):
    return {"status": 403, "message": "无权访问"}
注意两侧都必须用 realpath 规范化后的结果做前缀比较，不要用未规范化字符串 startswith 规范化字符串。若要彻底消除校验与打开之间的 TOCTOU 窗口，应改用 os.open(full, os.O_RDONLY | os.O_NOFOLLOW) 基于 fd 读取。

两侧都先取基名并校验最终路径仍落在预期根目录内：
user_root = os.path.realpath(os.path.join(STORAGE_ROOT, os.path.basename(user) or ""))
if not user_root.startswith(os.path.realpath(STORAGE_ROOT) + os.sep):
    return {"status": 400, "message": "非法用户目录"}
safe_name = os.path.basename(filename)
if not safe_name or safe_name in (".", ".."):
    return {"status": 400, "message": "非法文件名"}
path = os.path.realpath(os.path.join(user_root, safe_name))
if not path.startswith(user_root + os.sep):
    return {"status": 400, "message": "非法文件名"}
os.makedirs(user_root, exist_ok=True)
写入用临时文件 + os.replace 落盘，并在异常时 os.remove 残留文件，避免磁盘满或中断留下半截文件被后续 download 读到。

设定上限并分块读取，超限中断并返回 413；同时对用户做请求频率与总容量配额：
MAX_SIZE = 10 * 1024 * 1024
def read_upload(stream, max_size=MAX_SIZE):
    chunks, total = [], 0
    while True:
        chunk = stream.read(64 * 1024)
        if not chunk:
            break
        total += len(chunk)
        if total > max_size:
            raise ValueError("文件超出大小限制")
        chunks.append(chunk)
    return b"".join(chunks)
